import collections

def find_min_boxes_bfs(n):
    initial_state = tuple(sorted([1] * n))
    queue = collections.deque([initial_state])
    visited = {initial_state: n}
    min_boxes = n

    while queue:
        curr = queue.popleft()
        curr_boxes = len(curr)
        min_boxes = min(min_boxes, curr_boxes)
        if min_boxes == 1: return 1

        for i in range(len(curr)):
            for j in range(i + 1, len(curr)):
                m1 = curr[i]
                m2 = curr[j]
                # For speed, only try x that are divisors or specifically chosen?
                # Let's try all x first.
                for x in range(1, min(m1, m2) + 1):
                    new_boxes = []
                    for k in range(len(curr)):
                        if k != i and k != j:
                            new_boxes.append(curr[k])
                    new_boxes.append(m1 - x)
                    new_boxes.append(m2 - x)
                    new_boxes.append(2 * x)

                    new_boxes = sorted([b for b in new_boxes if b > 0])
                    new_state = tuple(new_boxes)

                    if new_state not in visited or visited[new_state] > len(new_boxes):
                        visited[new_state] = len(new_boxes)
                        queue.append(new_state)
    return min_boxes

